"""Migration of Meridian CRM invoiced-order transition and total recompute rules."""

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENTS = Decimal("0.01")


def _numeric(value: Any) -> Decimal:
    """Apply legacy NVL/numeric empty-string semantics."""
    if value is None:
        return Decimal("0")
    if isinstance(value, str) and value.strip() == "":
        return Decimal("0")
    return Decimal(str(value))


def _cents(value: Decimal) -> float:
    """Round using the legacy half-up monetary convention."""
    return float(value.quantize(_CENTS, rounding=ROUND_HALF_UP))


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply ORD-003 and the workflow's invoiced cancellation transition."""
    if order["STAT_CD"] != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    if new_status == "X":
        updated_order = dict(order)
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    if new_status == "I":
        return dict(order), [], []

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live-line extensions and the non-frozen order total."""
    copied_order = dict(order)
    copied_lines = [dict(line) for line in lines]

    # The legacy batch query excluded soft-deleted headers.
    if copied_order.get("DEL_FLG") == "Y":
        return copied_order, copied_lines, []

    # Modernized behavior: invoiced amounts are frozen; cancelled orders remain skipped.
    if copied_order["STAT_CD"] in ("I", "X"):
        return copied_order, copied_lines, []

    total = Decimal("0")

    for line in copied_lines:
        if line.get("DEL_FLG") == "Y":
            continue

        extension = _numeric(line.get("QTY")) * _numeric(line.get("UNIT_PRC"))
        rounded_extension = _cents(extension)
        line["EXT_AMT"] = rounded_extension
        total += Decimal(str(rounded_extension))

    discounted = total * (Decimal("100") - _numeric(copied_order.get("DISC_PCT"))) / Decimal("100")
    recomputed_total = _cents(discounted)

    changed = _numeric(copied_order.get("TOT_AMT")) != Decimal(str(recomputed_total))
    copied_order["TOT_AMT"] = recomputed_total

    return copied_order, copied_lines, ["ORD_RETOTAL"] if changed else []
